import { EgradxApiError } from '@babulvaibhav/egradx-client'

/*
 * Shared by the EGRADX recipes (shadcn registry items from @babulvaibhav/egradx-ui). Copied into your project like the rest of
 * a recipe: change the wording, the formats or the colours here and every recipe follows.
 */

/** Something to tell the person: wire it to your toasts (`sonner`'s `toast[tone](title, { description })`). */
export type Notify = (message: { tone: 'success' | 'info' | 'warning' | 'error'; title: string; description?: string }) => void

/** Used when a recipe is given no `onNotify`: messages are dropped, the screens still show errors inline. */
export const ignoreNotice: Notify = () => {}

/** Badge colours by meaning, for `<Badge variant="outline" className={tone.success}>`. */
export const tone = {
  success: 'border-emerald-500/30 bg-emerald-500/10 text-emerald-700 dark:text-emerald-400',
  warning: 'border-amber-500/30 bg-amber-500/10 text-amber-700 dark:text-amber-400',
  info: 'border-sky-500/30 bg-sky-500/10 text-sky-700 dark:text-sky-400',
  danger: 'border-destructive/30 bg-destructive/10 text-destructive',
  muted: 'text-muted-foreground',
} as const

const dateTime = new Intl.DateTimeFormat(undefined, { dateStyle: 'medium', timeStyle: 'short' })
const relative = new Intl.RelativeTimeFormat(undefined, { numeric: 'auto' })

export function formatDateTime(iso: string | null | undefined): string {
  return iso ? dateTime.format(new Date(iso)) : '—'
}

/** "3 minutes ago", "in 2 hours". */
export function formatRelative(iso: string | null | undefined): string {
  if (!iso) return '—'
  const seconds = (new Date(iso).getTime() - Date.now()) / 1000
  const units: [Intl.RelativeTimeFormatUnit, number][] = [['year', 31536000], ['month', 2592000], ['day', 86400], ['hour', 3600], ['minute', 60]]
  for (const [unit, size] of units) {
    if (Math.abs(seconds) >= size) return relative.format(Math.round(seconds / size), unit)
  }
  return relative.format(Math.round(seconds), 'second')
}

/** `oim.product_updated` → "Oim product updated". */
export function humanize(value: string | null | undefined): string {
  if (!value) return ''
  const words = value.replace(/[._-]+/g, ' ').trim().toLowerCase()
  return words.charAt(0).toUpperCase() + words.slice(1)
}

export function shortId(id: string): string {
  return id.slice(0, 8)
}

/** A channel id as people read it. Unknown ids, added by configuration, are shown as they are. */
export function channelLabel(id: string): string {
  const labels: Record<string, string> = { email: 'Email', sms: 'SMS', whatsapp: 'WhatsApp', slack: 'Slack', webhook: 'Webhook', log: 'Log' }
  return labels[id] ?? id
}

/** What went wrong, to show the person: the server's message, or a plain one. */
export function errorText(error: unknown): string {
  if (error instanceof EgradxApiError) {
    if (error.code === 'NETWORK_ERROR') return 'The server could not be reached. Check your connection and try again.'
    if (error.code === 'ACCESS_DENIED') return 'You do not have permission to do this.'
    return error.message
  }
  return error instanceof Error ? error.message : 'Something went wrong.'
}

export function errorCode(error: unknown): string | undefined {
  return error instanceof EgradxApiError ? error.code : undefined
}

'use client'

import { useEffect, useState, type ReactNode } from 'react'
import { Inbox, LoaderCircle, RefreshCw, Search, ShieldAlert, TriangleAlert, X } from 'lucide-react'
import {
  AlertDialog,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { cn } from '@/lib/utils'
import { errorCode, errorText } from './egradx-ui'

/* The small pieces every EGRADX recipe shares: empty and error states, a confirmation, a search box. */

interface StateProps {
  icon?: ReactNode
  title: ReactNode
  description?: ReactNode
  action?: ReactNode
  className?: string
}

export function EmptyState({ icon = <Inbox />, title, description, action, className }: StateProps) {
  return (
    <div className={cn('flex flex-col items-center justify-center gap-3 px-6 py-12 text-center', className)}>
      <div className="bg-muted text-muted-foreground flex size-12 items-center justify-center rounded-full [&_svg]:size-5">{icon}</div>
      <div className="space-y-1">
        <p className="font-medium">{title}</p>
        {description && <p className="text-muted-foreground mx-auto max-w-sm text-sm">{description}</p>}
      </div>
      {action}
    </div>
  )
}

/** A failed load: "not allowed" for a refusal, otherwise what went wrong, with a retry. */
export function ErrorState({ error, onRetry, className }: { error: unknown; onRetry?: () => void; className?: string }) {
  if (errorCode(error) === 'ACCESS_DENIED') {
    return (
      <EmptyState
        className={className}
        icon={<ShieldAlert />}
        title="Access restricted"
        description="Your role does not include this. Ask an administrator if you need it."
      />
    )
  }
  return (
    <EmptyState
      className={className}
      icon={<TriangleAlert className="text-destructive" />}
      title="Couldn't load this"
      description={errorText(error)}
      action={
        onRetry && (
          <Button variant="outline" size="sm" onClick={onRetry}>
            <RefreshCw /> Try again
          </Button>
        )
      }
    />
  )
}

interface ConfirmDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  title: ReactNode
  description?: ReactNode
  confirmLabel?: string
  destructive?: boolean
  pending?: boolean
  onConfirm: () => void
}

/** Asks before something that cannot be undone; stays open until the change is done. */
export function ConfirmDialog({ open, onOpenChange, title, description, confirmLabel = 'Confirm', destructive, pending, onConfirm }: ConfirmDialogProps) {
  return (
    <AlertDialog open={open} onOpenChange={(next) => !pending && onOpenChange(next)}>
      <AlertDialogContent>
        <AlertDialogHeader>
          <AlertDialogTitle>{title}</AlertDialogTitle>
          {description && <AlertDialogDescription>{description}</AlertDialogDescription>}
        </AlertDialogHeader>
        <AlertDialogFooter>
          <AlertDialogCancel disabled={pending}>Cancel</AlertDialogCancel>
          <Button variant={destructive ? 'destructive' : 'default'} disabled={pending} onClick={onConfirm}>
            {pending && <LoaderCircle className="animate-spin" />}
            {confirmLabel}
          </Button>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  )
}

/** A search box that reports what was typed once typing pauses. */
export function SearchBox({ value, onChange, placeholder = 'Search…', className }: { value: string; onChange: (value: string) => void; placeholder?: string; className?: string }) {
  const [draft, setDraft] = useState(value)
  useEffect(() => setDraft(value), [value])
  useEffect(() => {
    if (draft.trim() === value) return
    const timer = setTimeout(() => onChange(draft.trim()), 300)
    return () => clearTimeout(timer)
    // Only typing starts the timer.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [draft])
  return (
    <div className={cn('relative w-full sm:w-72', className)}>
      <Search className="text-muted-foreground pointer-events-none absolute top-1/2 left-3 size-4 -translate-y-1/2" />
      <Input value={draft} onChange={(event) => setDraft(event.target.value)} placeholder={placeholder} aria-label={placeholder} className="pr-8 pl-9" />
      {draft && (
        <button
          type="button"
          onClick={() => setDraft('')}
          className="text-muted-foreground hover:text-foreground absolute top-1/2 right-2 -translate-y-1/2 rounded p-0.5"
          aria-label="Clear search"
        >
          <X className="size-3.5" />
        </button>
      )}
    </div>
  )
}

'use client'

import { useState, type ReactNode } from 'react'
import { Bell, CheckCheck, Megaphone, RefreshCw, Settings } from 'lucide-react'
import type { InboxItem, StreamStatus } from '@babulvaibhav/egradx-client'
import { useInbox } from '@babulvaibhav/egradx-react'
import { Button } from '@/components/ui/button'
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover'
import { Skeleton } from '@/components/ui/skeleton'
import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/ui/tooltip'
import { cn } from '@/lib/utils'
import { formatRelative } from '../egradx-ui'

const STREAM: Record<StreamStatus, { label: string; dot: string }> = {
  open: { label: 'Live — receiving real-time updates', dot: 'bg-emerald-500' },
  connecting: { label: 'Connecting to live updates…', dot: 'bg-amber-500 animate-pulse' },
  reconnecting: { label: 'Connection lost — reconnecting…', dot: 'bg-amber-500 animate-pulse' },
  closed: { label: 'Live updates unavailable', dot: 'bg-destructive' },
  idle: { label: 'Live updates off', dot: 'bg-muted-foreground' },
}

interface NotificationBellProps {
  /** Where opening an item goes (from its `metadata`, say), or nothing for an item about nothing in particular. */
  linkFor?: (item: InboxItem) => string | undefined
  /** Goes to an item's link: your router's navigate. The list closes first. */
  onNavigate?: (link: string) => void
  /** Shows "Notification settings" at the foot of the list. */
  onOpenSettings?: () => void
  /** Each notification as it arrives live: announce it, refresh what it concerns. */
  onNotification?: (item: InboxItem) => void
  /** The icon for an item, by its `notificationKey`. Default: a bell, or a megaphone for announcements. */
  iconFor?: (item: InboxItem) => ReactNode
  /** Shown when there is nothing. */
  emptyText?: string
  pageSize?: number
}

/**
 * The signed-in person's notifications: the unread count, the list with older pages, live arrivals over the
 * stream, and read state (kept per person on the server). Follows sign-in, sign-out and organization switches.
 */
export function NotificationBell({ linkFor, onNavigate, onOpenSettings, onNotification, iconFor, emptyText = "You're all caught up.", pageSize = 20 }: NotificationBellProps) {
  const inbox = useInbox({ pageSize, onNotification })
  const [open, setOpen] = useState(false)
  const stream = STREAM[inbox.status]

  // Read state changes only when asked: opening an item, or "Mark read"; not merely opening the list. An item that
  // leads somewhere closes the list on the way; one that doesn't stays, with the rest.
  const openItem = (item: InboxItem) => {
    if (item.id && !item.readAt) void inbox.markRead(item.id)
    const link = linkFor?.(item)
    if (link && onNavigate) {
      setOpen(false)
      onNavigate(link)
    }
  }

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <Tooltip>
        <TooltipTrigger asChild>
          <PopoverTrigger asChild>
            <Button variant="ghost" size="icon" className="relative" aria-label={`Notifications (${inbox.unreadCount} unread)`}>
              <Bell />
              {inbox.unreadCount > 0 && (
                <span className="bg-primary text-primary-foreground absolute top-1 right-1 flex min-w-4 items-center justify-center rounded-full px-1 text-[10px] leading-4 font-semibold">
                  {inbox.unreadCount > 9 ? '9+' : inbox.unreadCount}
                </span>
              )}
              <span className={cn('ring-background absolute right-1.5 bottom-1.5 size-2 rounded-full ring-2', stream.dot)} />
            </Button>
          </PopoverTrigger>
        </TooltipTrigger>
        <TooltipContent>{stream.label}</TooltipContent>
      </Tooltip>
      <PopoverContent align="end" className="w-[min(92vw,380px)] p-0">
        <div className="flex items-center justify-between border-b px-4 py-3">
          <div>
            <p className="text-sm font-semibold">Notifications</p>
            <p className="text-muted-foreground flex items-center gap-1.5 text-xs">
              <span className={cn('size-1.5 rounded-full', stream.dot)} />
              {stream.label}
            </p>
          </div>
          <Button variant="ghost" size="sm" onClick={() => void inbox.markAllRead().catch(() => {})} disabled={inbox.unreadCount === 0}>
            <CheckCheck /> Mark read
          </Button>
        </div>
        <div className="max-h-[360px] overflow-y-auto">
          {inbox.loading ? (
            <div className="space-y-3 p-4">
              {[0, 1, 2].map((row) => (
                <div key={row} className="flex gap-3">
                  <Skeleton className="size-8 rounded-full" />
                  <div className="flex-1 space-y-2">
                    <Skeleton className="h-3 w-1/2" />
                    <Skeleton className="h-3 w-5/6" />
                  </div>
                </div>
              ))}
            </div>
          ) : inbox.error && inbox.items.length === 0 ? (
            <div className="text-muted-foreground flex flex-col items-center gap-2 px-6 py-10 text-center text-sm">
              Couldn't load notifications.
              <Button variant="outline" size="sm" onClick={() => void inbox.reload()}>
                <RefreshCw /> Try again
              </Button>
            </div>
          ) : inbox.items.length === 0 ? (
            <div className="text-muted-foreground flex flex-col items-center gap-2 px-6 py-10 text-center text-sm">
              <Bell className="size-5 opacity-60" />
              {emptyText}
            </div>
          ) : (
            <ul className="divide-y">
              {inbox.items.map((item) => {
                const unread = !item.readAt
                return (
                  <li key={item.id}>
                    <button type="button" onClick={() => openItem(item)} className={cn('hover:bg-muted/60 flex w-full gap-3 px-4 py-3 text-left', unread && 'bg-primary/5')}>
                      <div className="bg-muted text-muted-foreground flex size-8 shrink-0 items-center justify-center rounded-full [&_svg]:size-4">
                        {iconFor?.(item) ?? (item.scope === 'PLATFORM' ? <Megaphone /> : <Bell />)}
                      </div>
                      <div className="min-w-0 flex-1">
                        <div className="flex items-center justify-between gap-2">
                          <p className="truncate text-sm font-medium">{item.title}</p>
                          {unread && <span className="bg-primary size-1.5 shrink-0 rounded-full" aria-label="Unread" />}
                        </div>
                        {item.body && <p className="text-muted-foreground line-clamp-2 text-xs">{item.body}</p>}
                        <p className="text-muted-foreground/80 mt-1 text-[11px]">
                          {item.scope === 'PLATFORM' && 'Announcement · '}
                          {formatRelative(item.createdAt)}
                        </p>
                      </div>
                    </button>
                  </li>
                )
              })}
            </ul>
          )}
          {inbox.hasMore && (
            <div className="border-t p-2 text-center">
              <Button variant="ghost" size="sm" onClick={() => void inbox.loadMore()} disabled={inbox.loadingMore}>
                {inbox.loadingMore ? 'Loading…' : 'Load older'}
              </Button>
            </div>
          )}
        </div>
        {onOpenSettings && (
          <div className="border-t p-2">
            <Button
              variant="ghost"
              size="sm"
              className="w-full justify-start"
              onClick={() => {
                setOpen(false)
                onOpenSettings()
              }}
            >
              <Settings /> Notification settings
            </Button>
          </div>
        )}
      </PopoverContent>
    </Popover>
  )
}
